<script setup lang="ts">
import { newClientId } from '../lib/id';
import { computed, onBeforeUnmount, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { useRouter } from 'vue-router';
import { api, isMock } from '../api';
import type { Candidate, ImportJob } from '../api/types';
import { poll } from '../lib/poll';
import { candidateBlocker, candidateDraftWarning, normalizeCandidate } from '../lib/importing';
import { blankJudgeTemplate, languageLabel } from '../lib/problemCode';
const router = useRouter();
const importedLibraryId = ref(''); const text = ref(''); const title = ref(''); const file = ref<File>(); const mode = ref('text'); const busy = ref(false); const saving = ref(false); const error = ref(''); const job = ref<ImportJob>(); const selected = ref<string[]>([]); const confirmed = ref<string[]>([]); const activeIndex = ref(0); const committed = ref(false);
const current = computed(() => job.value?.candidates[activeIndex.value]);
const selectedCandidates = computed(() => job.value?.candidates.filter(c => selected.value.includes(c.candidateId)) ?? []);
const ready = computed(() => title.value.trim() && selectedCandidates.value.length && selectedCandidates.value.every(c => c.title.trim() && !c.unresolvedContent && !candidateBlocker(c) && c.samples.every(s => s.input !== null && s.output !== null) && confirmed.value.includes(c.candidateId)));
let controller = new AbortController(); let commitKey = ''; let commitSignature = '';
function sample() { text.value = '第1题：区间整数求和\n题干：输入两个整数，求闭区间内所有整数的和。\n输入格式：两个整数 a 和 b。\n输出格式：一个整数，表示区间和。\n输入样例：1 5\n输出样例：15\n分数：20\n\n第2题：数字的位数\n题干：读取一个整数，输出十进制位数。\n输入格式：一个整数 n。\n输出格式：输出位数，负号不计。\n输入样例：1024\n输出样例：4\n分数：20'; title.value = '循环结构练习'; }
function jsonSample() { text.value = JSON.stringify({ title: '函数练习', problems: [{ title: '计算函数', problemType: 'FUNCTION', language: 'CPP17', statement: '请实现题目指定的函数，具体计算要求待补充。', functionSignature: 'int calculate(int value);', starterCode: 'int calculate(int value) {\n    // 在这里完成函数\n}\n', judgeTemplate: '', referenceAnswer: '', samples: [], testCases: [], maxScore: 20, timeLimitMs: 1000, memoryLimitMb: 128 }] }, null, 2); title.value = '函数练习'; mode.value = 'text'; }
function chooseFile(event: Event) { const value = (event.target as HTMLInputElement).files?.[0]; if (!value) return; if (!/\.(txt|docx|json)$/i.test(value.name)) return ElMessage.warning('请选择 TXT、DOCX 或 JSON 文件'); if (value.size > 5 * 1024 * 1024) return ElMessage.warning('文件不能超过 5 MB'); file.value = value; }
async function parse() { busy.value = true; error.value = ''; committed.value = false; job.value = undefined; selected.value = []; confirmed.value = []; controller.abort(); controller = new AbortController(); try { const input = mode.value === 'file' ? file.value : text.value; if (!input || (typeof input === 'string' && !input.trim())) throw new Error('请粘贴题目材料或选择文件。'); const queued = await api.parse(input); const result = await poll(() => api.importJob(queued.id), j => ['READY', 'FAILED', 'COMMITTED'].includes(j.status), j => { job.value = { ...j, candidates: j.candidates.map(normalizeCandidate) }; }, controller.signal, isMock ? 300 : 1000); if (result.status === 'FAILED') throw new Error('解析失败，请检查材料格式后重试。'); selected.value = result.candidates.map(c => c.candidateId); activeIndex.value = 0; } catch (e) { if ((e as Error).name !== 'AbortError') error.value = (e as Error).message; } finally { busy.value = false; } }
function privateNotes(c: Candidate) { c.privateNotes += `${c.privateNotes ? '\n' : ''}${c.unresolvedContent}`; c.unresolvedContent = ''; }
async function commit() { if (!job.value || !ready.value) return; saving.value = true; error.value = ''; try { const signature = JSON.stringify({ id: job.value.id, title: title.value, candidates: selectedCandidates.value }); if (signature !== commitSignature) { commitSignature = signature; commitKey = newClientId(); } const result = await api.commit(job.value.id, title.value, selectedCandidates.value, commitKey); importedLibraryId.value = result.problemSetId; committed.value = true; job.value.status = 'COMMITTED'; ElMessage.success(`已创建 ${result.problemIds.length} 道题目草稿`); } catch (e) { error.value = (e as Error).message; } finally { saving.value = false; } }
onBeforeUnmount(() => controller.abort());
</script>
<template><div class="page import-page"><div class="page-heading"><div><h1>题目导入</h1><p>上传或粘贴题目材料，核对后保存为草稿。</p></div><span class="course-badge">教职工专用</span></div><div class="import-steps"><span :class="{ active: !job }"><b>01</b> 提供材料</span><i></i><span :class="{ active: job && !committed }"><b>02</b> 核对与修正</span><i></i><span :class="{ active: committed }"><b>03</b> 保存草稿</span></div><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb" /><template v-if="!job || busy"><section class="panel material-panel"><div class="section-bar"><h2>题目材料</h2><div class="action-group"><el-button link type="primary" @click="sample(); mode = 'text'">文本示例</el-button><el-button link type="primary" @click="jsonSample">JSON 函数题示例</el-button></div></div><el-tabs v-model="mode"><el-tab-pane label="粘贴文本 / JSON" name="text"><el-input v-model="text" type="textarea" :rows="14" placeholder="第1题：题目标题&#10;题干：…&#10;输入格式：…&#10;输出格式：…&#10;输入样例：…&#10;输出样例：…&#10;参考答案：…" aria-label="题目材料" /></el-tab-pane><el-tab-pane label="上传文件" name="file"><label class="file-drop"><strong>选择题目文档</strong><span>TXT / DOCX / JSON · 最大 5 MB（JSON 内容最多 1 MiB）</span><input type="file" accept=".txt,.docx,.json" @change="chooseFile" /><span v-if="file">已选择：{{ file.name }}</span></label><p v-if="isMock" class="demo-inline">演示模式仅支持文本与 TXT。</p></el-tab-pane></el-tabs><div class="material-footer"><p>参考答案与评测主程序仅教师可见。</p><el-button type="primary" size="large" :loading="busy" @click="parse">开始识别</el-button></div></section></template><div v-else-if="committed" class="panel completion-panel"><span class="completion-icon">✓</span><h2>题目已保存为草稿</h2><p>请在题库检查题目内容、测试用例与分值，再发布作业。</p><el-button type="primary" @click="router.push(`/teacher/problems/${importedLibraryId}`)">前往题库</el-button><el-button @click="job = undefined; committed = false">继续导入</el-button></div><template v-else><div class="import-summary panel"><div><strong>识别到 {{ job.candidates.length }} 道题目</strong><p>请核对题目内容及学生可见范围。</p></div><el-button @click="job = undefined">重新提供材料</el-button></div><el-empty v-if="!job.candidates.length" description="未识别出题目，请调整材料后重试。" /><div v-else class="import-grid"><aside class="candidate-list panel"><div v-for="(c, i) in job.candidates" :key="c.candidateId" class="candidate-item" :class="{ active: activeIndex === i }"><el-checkbox v-model="selected" :value="c.candidateId" :aria-label="`选择 ${c.title}`" /><button @click="activeIndex = i"><strong>{{ i + 1 }}. {{ c.title || '未命名题目' }}</strong><small>{{ languageLabel(c.language) }} · {{ c.problemType === 'FUNCTION' ? '函数题' : '程序题' }} · 第 {{ c.sourceLocation.startLine }}–{{ c.sourceLocation.endLine }} 行</small><span :class="confirmed.includes(c.candidateId) ? 'success' : 'warning'">{{ confirmed.includes(c.candidateId) ? '已核对' : '待核对' }}</span></button></div></aside><section v-if="current" class="candidate-editor panel"><div v-if="current.issues.length" class="issue-box"><strong>识别提示</strong><p v-for="(issue, index) in current.issues" :key="index">{{ issue.message }}</p></div><el-alert v-if="candidateBlocker(current)" :title="candidateBlocker(current)" type="error" :closable="false" class="mb" /><el-alert v-else-if="candidateDraftWarning(current)" :title="candidateDraftWarning(current)" type="warning" :closable="false" class="mb" /><el-form label-position="top"><h3 class="visibility-heading">学生可见内容</h3><el-form-item label="标题"><el-input v-model="current.title" /></el-form-item><div class="two-column"><el-form-item label="题目类型"><el-select v-model="current.problemType"><el-option label="完整程序题" value="PROGRAM" /><el-option label="函数题" value="FUNCTION" /></el-select></el-form-item><el-form-item label="语言"><el-select v-model="current.language"><el-option label="C" value="C17" /><el-option label="C++" value="CPP17" /></el-select></el-form-item></div><el-form-item v-if="current.problemType === 'FUNCTION'" label="函数接口（公开）"><el-input v-model="current.functionSignature" type="textarea" :rows="3" class="mono-input" /></el-form-item><el-form-item label="起始代码（公开）"><el-input v-model="current.starterCode" type="textarea" :rows="4" class="mono-input" placeholder="只放函数骨架或程序起始模板，不放参考实现。" /></el-form-item><el-form-item label="题干"><el-input v-model="current.statement" type="textarea" :rows="4" /></el-form-item><div class="two-column"><el-form-item label="输入格式"><el-input v-model="current.inputDescription" type="textarea" /></el-form-item><el-form-item label="输出格式"><el-input v-model="current.outputDescription" type="textarea" /></el-form-item></div><div v-for="(s, i) in current.samples" :key="i" class="two-column"><el-form-item :label="`样例 ${i + 1} 输入${s.input === null ? '（未提供）' : ''}`"><el-input :model-value="s.input ?? ''" @update:model-value="s.input = $event" type="textarea" /></el-form-item><el-form-item :label="`样例 ${i + 1} 输出${s.output === null ? '（未提供）' : ''}`"><el-input :model-value="s.output ?? ''" @update:model-value="s.output = $event" type="textarea" /></el-form-item></div><el-form-item v-for="(sample, index) in current.samples" :key="`explanation-${index}`" :label="`样例 ${index + 1} 说明（公开，可选）`"><el-input :model-value="sample.explanation ?? ''" @update:model-value="sample.explanation = $event" type="textarea" /></el-form-item><div class="two-column"><el-form-item label="时间限制（ms）"><el-input-number v-model="current.timeLimitMs" :min="100" :max="10000" /></el-form-item><el-form-item label="内存限制（MB）"><el-input-number v-model="current.memoryLimitMb" :min="16" :max="512" /></el-form-item></div><el-form-item label="代码长度限制（字节）"><el-input-number v-model="current.codeLimitBytes" :min="1024" :max="262144" /></el-form-item><el-form-item label="题目分值"><el-input-number :model-value="current.maxScore ?? undefined" @update:model-value="current.maxScore = $event ?? null" :min="1" :max="1000" placeholder="待补充" /></el-form-item><h3 class="visibility-heading private">教师私有内容</h3><el-form-item v-if="current.problemType === 'FUNCTION' || current.judgeTemplate" label="评测主程序（私有）"><el-input v-model="current.judgeTemplate" type="textarea" :rows="7" class="mono-input" placeholder="缺失时可暂存草稿，发布前补齐唯一 /*__STUDENT_CODE__*/ 标记的主程序。" /><el-button class="mt" size="small" :disabled="!!current.judgeTemplate.trim() || current.problemType !== 'FUNCTION'" @click="current.judgeTemplate = blankJudgeTemplate(current.language)">填入空白框架</el-button></el-form-item><el-form-item label="参考答案"><el-input v-model="current.referenceAnswer" type="textarea" :rows="5" class="mono-input" placeholder="缺失时可暂存草稿，发布前补齐。" /></el-form-item><div v-for="(test, index) in current.testCases" :key="index" class="test-editor"><h3>私有测试点 {{ index + 1 }}</h3><div class="two-column"><el-form-item label="输入"><el-input :model-value="test.input ?? ''" @update:model-value="test.input = $event" type="textarea" /></el-form-item><el-form-item label="预期输出"><el-input :model-value="test.expectedOutput ?? ''" @update:model-value="test.expectedOutput = $event" type="textarea" /></el-form-item></div><div class="action-group"><el-select v-model="test.visibility" style="width:130px"><el-option label="隐藏" value="HIDDEN" /><el-option label="公开" value="PUBLIC" /></el-select><el-select v-model="test.comparisonMode" style="width:150px"><el-option label="精确比较" value="EXACT" /><el-option label="按空白分词" value="TOKENS" /></el-select><el-input-number :model-value="test.score ?? undefined" @update:model-value="test.score = $event ?? null" :min="0" /></div></div><el-form-item label="教师备注（保存在本次导入记录中）"><el-input v-model="current.privateNotes" type="textarea" :rows="3" /></el-form-item><div v-if="current.unresolvedContent" class="issue-box"><strong>需要确认归属的原文</strong><pre>{{ current.unresolvedContent }}</pre><el-button @click="privateNotes(current)">移至教师备注</el-button></div><el-checkbox v-model="confirmed" :value="current.candidateId" :disabled="!!current.unresolvedContent">我已核对字段及公开范围</el-checkbox></el-form></section></div><div class="commit-bar panel"><el-input v-model="title" placeholder="题库名称，例如：第三章循环结构练习" aria-label="题库名称" /><span>已选 {{ selected.length }} 题</span><el-button type="primary" :disabled="!ready" :loading="saving" @click="commit">确认并保存草稿</el-button></div></template></div></template>
